INSERT INTO unit_detail (slug, author, author_short, title_arabic, title_language, study_track, blurb_html, edition_note, cover_key, pdf_key, published_at, source_commit) VALUES ('surah-al-fateha', 'Asif Hussain', 'Asif Hussain', 'سورة الفاتحة', 'ar', 'theology', '<p>This book is a series of spoken sessions, delivered aloud to an audience and afterward set down as prose. It takes the opening chapter of the Quran, Surah Al-Fateha, and reads it slowly, almost phrase by phrase, drawing out of each word far more than a first hearing would suggest is there.</p>', NULL, 'surah-al-fateha/cover.png', 'surah-al-fateha/book.pdf', '2026-09-03T16:57:29Z', 'f566f5a1bcc12253290b16c52aaa8ab98c71d8c1');
