INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 1, 'What is Worship?', 'we look at the linguistic meaning of ''worship''.', 'lecture', 'surah-al-fateha/audio/ep01.mp3', 'surah-al-fateha/transcript/ep01.vtt', 1238, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 2, 'The Womb Of Afterlife', 'we study the HADEES of Rasul Allah(Salallahu alayhi wa aalihee wa sallam) in which he compares the life of this world to the womb.', 'lecture', 'surah-al-fateha/audio/ep02.mp3', 'surah-al-fateha/transcript/ep02.vtt', 1730, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 3, 'Allah - Being vs Attributes', 'we study the distinction of ''being'' vs ''attributes'', leading to the conversation about transcendence vs immanence. Finally, we look at the powerful word Allah uses to explain how we can understand him.', 'lecture', 'surah-al-fateha/audio/ep03.mp3', 'surah-al-fateha/transcript/ep03.vtt', 2162, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 4, 'The ISM Of Allah', 'we explore the linguistic meaning of ISM', 'lecture', 'surah-al-fateha/audio/ep04.mp3', 'surah-al-fateha/transcript/ep04.vtt', 1758, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 5, 'In the Name Of Allah The Merciful', 'we study the phrase in its linguistic context to understand its purpose.', 'lecture', 'surah-al-fateha/audio/ep05.mp3', 'surah-al-fateha/transcript/ep05.vtt', 1797, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 6, 'Linguistic Perfection Of HAMD', 'we closely examine the perfection in the use of the word HAMD in this verse.', 'lecture', 'surah-al-fateha/audio/ep06.mp3', 'surah-al-fateha/transcript/ep06.vtt', 2225, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 7, 'Abundant and Consistent Mercy', 'we reflect on the infinite blessings of Allah(Subhanahu wa Ta''ala)', 'lecture', 'surah-al-fateha/audio/ep07.mp3', 'surah-al-fateha/transcript/ep07.vtt', 2999, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 8, 'Day Of Judgment - Linguistics', 'we do a linguistic study of the verse', 'lecture', 'surah-al-fateha/audio/ep08.mp3', 'surah-al-fateha/transcript/ep08.vtt', 1517, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 9, 'Motivating Factors For Piety', 'We study how this verse motivates us towards piety in several ways.', 'lecture', 'surah-al-fateha/audio/ep09.mp3', 'surah-al-fateha/transcript/ep09.vtt', 2750, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 10, 'Worship and Assistance', 'we linguistically study the meaning of the fourth verse regarding worship and assistance.', 'lecture', 'surah-al-fateha/audio/ep10.mp3', 'surah-al-fateha/transcript/ep10.vtt', 1976, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 11, 'Guidance To The Straight Path', 'we understand the concept of asking Allah(Subhanahu wa Ta''ala) for guidance towards the straight path of those that received his favors; not of those who received anger or strayed.', 'lecture', 'surah-al-fateha/audio/ep11.mp3', 'surah-al-fateha/transcript/ep11.vtt', 2621, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 12, 'Staying Steadfast On The Path', 'we discuss a practical way of remaining steadfast on the straight path', 'lecture', 'surah-al-fateha/audio/ep12.mp3', 'surah-al-fateha/transcript/ep12.vtt', 3657, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 13, 'Quranic Friendship', 'we look at the Quranic descriptions of the various shades of friendship.', 'lecture', 'surah-al-fateha/audio/ep13.mp3', 'surah-al-fateha/transcript/ep13.vtt', 4215, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 14, 'The Stages Of Love', 'we look at the 10 stages of love as it increases in intensity. The finally stage MUHABBAH being the culmination of all 10 stages.', 'lecture', 'surah-al-fateha/audio/ep14.mp3', 'surah-al-fateha/transcript/ep14.vtt', 4110, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 15, 'Linguistic Meaning Of Allah', 'we look at the various linguistic meanings of the word ILAH to create a complete understanding of the word Allah. The goal of this session is to realize the position and role Allah should have in our lives, and how we can begin the journey towards that recognition.', 'lecture', 'surah-al-fateha/audio/ep15.mp3', 'surah-al-fateha/transcript/ep15.vtt', 3884, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 16, 'Linguistic Meaning Of REHMA', 'we study the linguistic meaning of the composite word REHMA and it''s two famous derivatives of AL-REHMAN and AL-RAHEEM.', 'lecture', 'surah-al-fateha/audio/ep16.mp3', 'surah-al-fateha/transcript/ep16.vtt', 3419, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 17, 'Womb - The Source Of Mercy', 'we study the root word from which REHMA is derived - the primary word for Allah''s love and compassion.', 'lecture', 'surah-al-fateha/audio/ep17.mp3', 'surah-al-fateha/transcript/ep17.vtt', 3491, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 18, 'Manifestations of REHMA', 'we look at some of the common manifestations of REHAM through forgiveness and rewards', 'lecture', 'surah-al-fateha/audio/ep18.mp3', 'surah-al-fateha/transcript/ep18.vtt', 2763, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 19, 'Linguistic Meaning Of Rabb', 'we study the various meanings that come together to make up the word RAB.', 'lecture', 'surah-al-fateha/audio/ep19.mp3', 'surah-al-fateha/transcript/ep19.vtt', 3291, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 20, 'Master Slave Relationship', 'we take a look at the relationship that Allah offers as our master, and how we can complete that relationship to reap its benefits.', 'lecture', 'surah-al-fateha/audio/ep20.mp3', 'surah-al-fateha/transcript/ep20.vtt', 3913, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 21, 'Understanding RAB Al-ALAMEEN', 'we begin exploring the word ''ALAMEEN'' to understand how Allah created this universe as a tool for his recognition.We then look at one of the interpretations of the term RAB Al-ALAMEEN to learn the lesson of humility', 'lecture', 'surah-al-fateha/audio/ep21.mp3', 'surah-al-fateha/transcript/ep21.vtt', 2850, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 22, 'The Divine Formula For Recognizing Allah', 'we look at the Quranic formula to understand who Allah is and what he wants from his creation.', 'lecture', 'surah-al-fateha/audio/ep22.mp3', 'surah-al-fateha/transcript/ep22.vtt', 3792, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('surah-al-fateha', 23, 'The Horizons And The Soul', 'we learn the purpose of man''s creation and the reason Quran reveals the attributes of the creator.', 'lecture', 'surah-al-fateha/audio/ep23.mp3', 'surah-al-fateha/transcript/ep23.vtt', 3206, NULL);
